sys_script_include.script:
var CreateIntegrationValueBuilderTask = Class.create();
CreateIntegrationValueBuilderTask.prototype = {
    initialize: function() {
    },
createTasksFromProperty: function() {
        var propertyName = 'sam.integration'; // Update with actual property name
        var propertyValue = gs.getProperty(propertyName);

        if (!propertyValue) {
            gs.error('System property "' + propertyName + '" is empty or not set.');
            return;
        }

        try {
            var integrationData = JSON.parse(propertyValue);
            var createdTasks = [];

            for (var i = 0; i < integrationData.length; i++) {
                var integration = integrationData[i];
                var title = integration.title;
                var description = integration.description || 'No description available';
                var shortDescription = 'Integration Task for ' + title;
                var instructions = this.buildInstructions(integration);

                var existingTask = new GlideRecord('samp_sp_vb_task');
                existingTask.addQuery('short_description', shortDescription);
                existingTask.query();

                if (existingTask.next()) {
                    existingTask.setValue('description', description);
                    existingTask.setValue('instructions', instructions);
                    existingTask.update();
                    gs.info('Updated existing task for: ' + title);
                } else {
                    var newTask = new GlideRecord('samp_sp_vb_task');
                    newTask.initialize();
                    newTask.setValue('short_description', shortDescription);
                    newTask.setValue('description', description);
                    newTask.setValue('instructions', instructions);
                    var taskId = newTask.insert();

                    if (taskId) {
                        gs.info('Created new task for: ' + title);
                        createdTasks.push(title);
                    }
                }
            }

            gs.info('Completed processing system property "' + propertyName + '". Created Tasks: ' + createdTasks.join(', '));
        } catch (e) {
            gs.error('Error processing system property "' + propertyName + '": ' + e.message);
        }
    },

    buildInstructions: function(integration) {
        var instructions = 'Follow the steps to integrate: ' + integration.title + '\n';

        if (integration.dataForTree) {
            for (var j = 0; j < integration.dataForTree.length; j++) {
                var section = integration.dataForTree[j];
                instructions += '\n' + section.label + ':\n';

                if (section.children) {
                    for (var k = 0; k < section.children.length; k++) {
                        var item = section.children[k];
                        instructions += '- ' + item.label + '\n';
                    }
                }
            }
        }

        return instructions;
    },

    type: 'CreateIntegrationValueBuilderTask'
};
